<?php
require_once __DIR__.'/../backend/config/config.php';
$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM products WHERE is_active=1) products,(SELECT COUNT(*) FROM users WHERE role='Customer') customers,(SELECT COUNT(*) FROM orders) orders,(SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE status<>'Cancelled') revenue")->fetch();
$products=$pdo->query("SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();
$orders=$pdo->query("SELECT order_id,customer_name,total_amount,status,created_at FROM orders ORDER BY created_at DESC LIMIT 15")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bhaskar Store Admin</title><style>body{font-family:Arial;background:#f5f3ef;color:#181818;margin:0}.wrap{width:92%;max-width:1180px;margin:auto}header{background:#181818;color:#fff;padding:22px 0}h1{margin:0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:25px 0}.card,section{background:#fff;border:1px solid #ddd8cf;padding:20px}.card b{font-size:28px;display:block;margin-top:8px}section{margin:20px 0}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px;border-bottom:1px solid #eee;font-size:13px}img{width:50px;height:60px;object-fit:cover}@media(max-width:700px){.cards{grid-template-columns:1fr 1fr}table{display:block;overflow:auto;white-space:nowrap}}</style></head><body><header><div class="wrap"><h1>ECOMMERCE — ADMIN</h1><p>Inventory, customers and order overview</p></div></header><main class="wrap"><div class="cards"><div class="card">Products<b><?= (int)$stats['products'] ?></b></div><div class="card">Customers<b><?= (int)$stats['customers'] ?></b></div><div class="card">Orders<b><?= (int)$stats['orders'] ?></b></div><div class="card">Revenue<b>₹<?= number_format((float)$stats['revenue'],2) ?></b></div></div><section><h2>Recent Orders</h2><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Date</th></tr><?php foreach($orders as $o): ?><tr><td><?=htmlspecialchars($o['order_id'])?></td><td><?=htmlspecialchars($o['customer_name'])?></td><td>₹<?=number_format($o['total_amount'],2)?></td><td><?=htmlspecialchars($o['status'])?></td><td><?=htmlspecialchars($o['created_at'])?></td></tr><?php endforeach; ?></table></section><section><h2>Inventory</h2><table><tr><th>Image</th><th>Product</th><th>Category</th><th>Price</th><th>Stock</th></tr><?php foreach($products as $p): ?><tr><td><img src="<?=htmlspecialchars($p['image_url'])?>"></td><td><?=htmlspecialchars($p['name'])?></td><td><?=htmlspecialchars($p['category'])?></td><td>₹<?=number_format($p['selling_price'],2)?></td><td><?=htmlspecialchars($p['stock'])?></td></tr><?php endforeach; ?></table></section></main></body></html>
